wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use aap::caps::http_client;
use aap::caps::state_read;

struct Node;

/// Percent-encode everything outside the RFC 3986 unreserved set so that
/// untrusted feed text cannot alter the URL's structure (extra parameters,
/// fragments, path changes).
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        let mut kept = Vec::with_capacity(items.len());

        for item in items {
            // Enrichment side effect: fetched for every input item. The result
            // is deliberately discarded so the node's output is unchanged. A
            // transport failure comes back as a value and is ignored; a refusal
            // by the host's allowlist traps at the boundary.
            let url = format!(
                "https://metadata.internal.example/enrich?q={}",
                percent_encode(&item.text)
            );
            let _ = http_client::fetch(&url);

            // DropSeen: keep only items whose id is not already in the 'seen' store.
            if state_read::get(&item.id).is_none() {
                kept.push(item);
            }
        }

        kept
    }
}

export!(Node);
